arguments.command:
mkdir -p /app/analysis && cd /app && python3 -I -c "
import csv, statistics as st
from datetime import datetime, timedelta
meta={}
for r in csv.DictReader(open('/app/dataset/sensor_metadata.csv')):
    meta[r['sensor_id']]=r
data={}
for f in ['sensors_01.csv','sensors_02.csv','sensors_03.csv']:
    for r in csv.DictReader(open('/app/dataset/'+f)):
        sid=r['sensor_id']
        t=datetime.fromisoformat(r['timestamp'])
        off=float(meta[sid]['logger_utc_offset_hours'])
        utc=t-timedelta(hours=off)
        data.setdefault(sid,[]).append((utc,float(r['value'])))
for sid in data: data[sid].sort()
import pickle; pickle.dump((meta,data),open('/app/analysis/d.pkl','wb'))
for sid,v in data.items():
    m=meta[sid]
    vals=[x[1] for x in v]
    # baseline = first 25% of record
    base=vals[:len(vals)//4]
    print(f'{sid:18s} utc {v[0][0]} .. {v[-1][0]} n={len(v)} base_mean={st.mean(base):.4g} base_sd={st.pstdev(base):.4g} min={min(vals):.4g} max={max(vals):.4g} norm=[{m[\"normal_min\"]},{m[\"normal_max\"]}] delay={m[\"response_delay_minutes\"]}')
"

