arguments.command:
python3 -I -c "
import csv
from datetime import datetime
# Raw (unconverted) timestamps of the three stuck segments vs alarm times (which are UTC 'Z')
want={'TURB_OUTPUT_01':770.0,'STEAM_PRES_01':71.5,'COOLING_PRES_01':12.6}
for f in ['sensors_01.csv','sensors_02.csv','sensors_03.csv']:
    for r in csv.DictReader(open('/app/dataset/'+f)):
        sid=r['sensor_id']
        if sid in want and abs(float(r['value'])-want[sid])<1e-9:
            print('%-16s RAW file ts = %s  (file %s)'%(sid,r['timestamp'],f)); want.pop(sid)
" ; echo "--- alarm first-fire (UTC Z) ---"; grep -m1 TURB_OUTPUT /app/dataset/alarms.csv; grep -m1 STEAM_PRES /app/dataset/alarms.csv; grep -m1 COOLING_PRES /app/dataset/alarms.csv

